def main():
    existing = get_existing_norms(exclude_slugs={"cv-topic-c1-extended"})
    entries = []
    skipped = 0
    rank = 1

    for row in ITEMS:
        kind = row[0]
        headword = row[1]
        norm = norm_vocab(headword)
        if norm in existing:
            skipped += 1
            continue

        if kind == "noun":
            gender = row[2]
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            art = "El" if gender == "m" else "La"
            ex_es = f"{art} {headword} resulta fundamental en los análisis avanzados."
            ex_ar = f"يعد الـ{msa} أساسياً في التحليلات المتقدمة والبحوث المتعمقة."
            entry = make_noun(headword, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "verb":
            paradigm = row[2]
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            ex_es = f"Es preciso {headword} con rigor y objetividad en todo momento."
            ex_ar = f"يلزم أن {msa} بدقة وموضوعية في جميع الأوقات."
            clean_hw = headword.strip()
            is_single_inf = " " not in clean_hw and (clean_hw.endswith(("ar", "er", "ir", "arse", "erse", "irse")))
            if is_single_inf:
                entry = make_verb(headword, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
            else:
                entry = make_expr(headword, "collocation", level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "adj":
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            ex_es = f"Se trata de un aspecto verdaderamente {headword} en este contexto."
            ex_ar = f"يتعلق الأمر بجانب {msa} حقاً في هذا السياق المحدد."
            entry = make_adj(headword, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        elif kind == "expr":
            expr_kind = row[2]
            level = row[3]
            msa = row[4]
            eg = row[5]
            domain = row[6]
            ex_es = f"En este sentido, {headword}, conviene mantener la claridad expositiva."
            ex_ar = f"في هذا السياق، {msa}، يحسن الحفاظ على وضوح العرض والبيان."
            entry = make_expr(headword, expr_kind, level, msa, eg, ex_es, ex_ar, domain=domain, rank=rank)
        else:
            continue

        entries.append(entry)
        existing.add(norm)
        rank += 1

    print(f"C1 Extended: Prepared {len(entries)} new entries (skipped {skipped} existing).")
    emit_bundle("vocab-cv-topic-c1-extended.json", "cv-topic-c1-extended", "معجم الإسبانية المتقدمة الموسع C1 و B2", entries)

if __name__ == "__main__":
    main()
